mapper.select:
SELECT



    a.is_deleted = 0

        AND (a.receiver_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR a.receiver_phone LIKE CONCAT('%', #{q.keyword}, '%'))


        AND a.user_id = #{q.userId}


        AND a.tag = #{q.tag}


        AND a.is_default = #{q.isDefault}


        AND a.create_time >= #{q.beginTime}


        AND a.create_time <= #{q.endTime}



ORDER BY a.is_default DESC, a.id DESC
